catalog_script_client.script:
function onLoad() {
    applyLiveMask('v_despesa_bruta_com_pessoal');
    applyLiveMask('v_despesa_com_pessoal_ativo');
    applyLiveMask('v_despesa_com_pessoal_inativo_e_pensionistas');
    applyLiveMask('v_despesa_com_pessoal_terceirizado');
    applyLiveMask('v_despesa_com_deducoes');
    applyLiveMask('v_indenizacoes_por_demissao_ou_por_incentivo_a_demissao_voluntaria');
    applyLiveMask('v_despesas_com_indenizaces_de_decisoes_judiciais');
    applyLiveMask('v_despesas_de_exercicio_anteriores');
    applyLiveMask('v_interface_a_pensionistas_com_resumos_vinculados');
    applyLiveMask('v_despesa_liquida_com_pedidos');
    applyLiveMask('v_receita_corrente_liquidos_sel_7406a_fibo_de_medidas');
    applyLiveMask('v_receita_corrente_liquida_rcl');
    applyLiveMask('v_despesa_total_com_pessoal_executivo_anual');
    applyLiveMask('v_despesa_liquida_pessoal_executivo');
    applyLiveMask('v_despesa_liquida_pessoal_consolidado');
}

function applyLiveMask(variableName) {
    var field = g_form.getControl(variableName);
    if (!field) return;

    field.addEventListener('input', function(e) {
        let raw = field.value.replace(/[^\d]/g, '');
        if (!raw) {
            field.value = '';
            return;
        }
        let number = parseFloat(raw) / 100;
        let formatted = number.toLocaleString('pt-BR', {
            style: 'currency',
            currency: 'BRL'
        });
        field.value = formatted;
        field.setSelectionRange(formatted.length, formatted.length);
    });

    field.addEventListener('paste', function(e) {
        let pasted = (e.clipboardData || window.clipboardData).getData('text');
        if (/[^\d]/.test(pasted.replace(/[^\d]/g, ''))) {
            e.preventDefault();
        }
    });
}
